// Temporary browser fixture. Every worker/test record is explicitly MOCK.
// Production databases and provider connections are never used here.
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {randomUUID} from 'node:crypto';import {once} from 'node:events';
import {createApp} from '../../src/app.js';import {loadConfig} from '../../src/config/index.js';
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'stage4-output-browser-')),workers={call:async(_agent,packet)=>({report:'MOCK worker report for UI verification',files:packet.phase==='builder'?[{path:'add.mjs',content:'export const add=(a,b)=>a+b;'}]:[],...(packet.phase==='reviewer'?{review:{...packet.reviewBinding,decision:'approved',summary:'MOCK review of recorded test evidence only',findings:[]}}:{})}),tests:async(_root,_signal,record)=>{const common={fixtureOnly:true,command:['MOCK','node','--test','add.test.mjs'],revisionHash:'mock-revision',startedAt:new Date().toISOString()};record({kind:'execution_started',content:common});record({kind:'execution_finished',content:{...common,exit:0,durationMs:5,stdout:'MOCK OUTPUT ONLY: ok 1 - finite number addition',stderr:''}});return {executed:true,passed:true,fixtureOnly:true,count:1,failed:0,revisionHash:'mock-revision',summary:'MOCK one test passed; no subprocess ran.',names:[{name:'MOCK finite number addition',passed:true,durationMs:5}]};}};
const r=createApp(loadConfig({DATABASE_PATH:path.join(dir,'main.sqlite'),WORKSPACE_DIR:path.join(dir,'projects'),BACKUP_DIR:path.join(dir,'backups')}),{fetchImpl:async()=>{throw Error('Provider network forbidden in UI fixture');},studioOptions:{workers}}),p=r.team.studio.project({name:'MOCK ONLY · Stage 4 output rendering'}),c=r.team.studio.create(p.id,'MOCK ONLY: output and review history');r.team.studio.start(p.id,{chatId:c.id,requestId:randomUUID()});
const server=r.app.listen(0,'127.0.0.1');await once(server,'listening');console.log('MOCK dashboard: http://127.0.0.1:'+server.address().port+'/team#project/'+p.id+'/chat/'+c.id);
let closing=false;async function close(){if(closing)return;closing=true;await r.team.studio.close();r.team.preview.close();r.team.messenger.close();server.closeAllConnections();server.close(()=>{r.db.close();fs.rmSync(dir,{recursive:true,force:true});});}process.on('SIGINT',close);process.on('SIGTERM',close);
